1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = { yearsWithMHPCO: number };
14	
15	export type Scenario = {
16	  customer: Customer;
17	  steps: QuoteStep[];
18	};
19	
20	export type ScenarioResults = {
21	  results: unknown[];
22	};
23	
24	const PROCESSING_FEE = 5;
25	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
26	const LOYALTY_DISCOUNT = 0.2;
27	const LOYALTY_YEARS = 2;
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const BLOCK_SIZE = 3;
39	const BLOCK_BASE_PREMIUM = 60;
40	
41	const COMPONENT_TYPES = ["rune", "moonstone"];
42	
43	/** Items are priced per type, because the component block applies to alike items. */
44	const groupByType = (items: Item[]): Map<string, Item[]> =>
45	  items.reduce(
46	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
47	    new Map<string, Item[]>(),
48	  );
49	
50	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
51	
52	/**
53	 * Item-level risk surcharges, each a rate on the item's own base premium.
54	 * They are separate addends: unlike the policy-level initial assessment, they
55	 * do not compound with each other or with it.
56	 */
57	const CURSE_SURCHARGE = 0.5;
58	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
59	const HIGH_ENCHANTMENT_LEVEL = 5;
60	
61	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
62	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
63	  {
64	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
65	    rate: HIGH_ENCHANTMENT_SURCHARGE,
66	  },
67	];
68	
69	const itemSurchargeTotal = (item: Item): number =>
70	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
71	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
72	    0,
73	  );
74	
75	/**
76	 * A building block of exactly 3 alike components is offered at a special base
77	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
78	 * runes are charged per item.
79	 */
80	const formsComponentBlock = (type: string, items: Item[]): boolean =>
81	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
82	
83	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
84	  formsComponentBlock(type, items)
85	    ? BLOCK_BASE_PREMIUM
86	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  [...groupByType(items)].reduce(
90	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
91	    0,
92	  );
93	
94	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
95	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
96	
97	/**
98	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
99	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
100	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
101	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
102	 */
103	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
104	
105	const policyItemSurchargeTotal = (items: Item[]): number =>
106	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
107	
108	/**
109	 * The premium is the policy base premium plus a set of independent addends,
110	 * each a rate on that same base — they do not compound with one another:
111	 *
112	 *   100 base + 50 curse + 30 high ench + 10 first insurance = 190, + 5 fee
113	 *
114	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
115	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
116	 * documented there.
117	 */
118	/** Long-standing customers receive a loyalty discount on the policy base premium. */
119	const loyaltyDiscount = (basePremium: number, customer: Customer): number =>
120	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;
121	
122	const quote = (step: QuoteStep, customer: Customer): { premium: number } => {
123	  const basePremium = policyBasePremium(step.items);
124	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
125	  const itemSurcharges = policyItemSurchargeTotal(step.items);
126	
127	  return {
128	    premium: roundInMHPCOsFavour(
129	      assessedPremium + itemSurcharges - loyaltyDiscount(basePremium, customer) + PROCESSING_FEE,
130	    ),
131	  };
132	};
133	
134	export const runScenario = (scenario: Scenario): ScenarioResults => ({
135	  results: scenario.steps.map((step) => quote(step, scenario.customer)),
136	});
