/**
 * The premium is the policy base premium plus a set of independent addends,
 * each a rate on that same base — they do not compound with one another:
 *
 *   100 base + 50 curse + 30 high ench + 10 first insurance = 190, + 5 fee
 *
 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
 * documented there.
 */
/** Long-standing customers receive a loyalty discount on the policy base premium. */
const loyaltyDiscount = (basePremium: number, customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;

const quote = (step: QuoteStep, customer: Customer): { premium: number } => {
  const basePremium = policyBasePremium(step.items);
  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
  const itemSurcharges = policyItemSurchargeTotal(step.items);

  return {
    premium: roundInMHPCOsFavour(
      assessedPremium + itemSurcharges - loyaltyDiscount(basePremium, customer) + PROCESSING_FEE,
    ),
  };
};

